package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct {
	ScAcct  string
	ScPrin  decimal.Decimal
	ScRate  decimal.Decimal
	ScYears int64
}

var WsEofFlag string = "N"
var WsBal decimal.Decimal = decimal.New(0, 0)
var WsYear int64 = 0
var WsCount int64 = 0
var WsBalEd string = ""

var schedRec SchedRec

var schedLines []string
var schedIndex int
var schedFile *os.File

func parseDigitsToDecimal(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.New(0, 0)
	}
	// keep only digits, if spaces treat as 0
	clean := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			clean += string(ch)
		} else if ch == ' ' {
			clean += "0"
		}
	}
	if clean == "" {
		return decimal.New(0, 0)
	}
	// parse as integer
	d, err := decimal.NewFromString(clean)
	if err != nil {
		return decimal.New(0, 0)
	}
	return d.Shift(-scale)
}

func parseIntField(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	clean := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			clean += string(ch)
		}
	}
	if clean == "" {
		return 0
	}
	var v int64
	fmt.Sscanf(clean, "%d", &v)
	return v
}

func truncateToPic9_8V99(d decimal.Decimal) decimal.Decimal {
	// PIC 9(8)V99 : integer digits 8, scale 2, unsigned
	// keep low-order integer digits
	// work with absolute value; all balances are positive here
	neg := d.IsNegative()
	if neg {
		d = d.Neg()
	}
	// separate integer and fraction
	intPart := d.Truncate(0)
	fracPart := d.Sub(intPart) // 0 <= frac <1, with scale 2
	// modulo 10^8 for integer part
	modulus := decimal.New(100000000, 0) // 10^8
	if intPart.GreaterThanOrEqual(modulus) || intPart.GreaterThanOrEqual(decimal.New(100000000, 0)) {
		intPart = intPart.Mod(modulus)
		// For decimal Mod, shopspring Mod works
	}
	newVal := intPart.Add(fracPart)
	if neg {
		newVal = newVal.Neg()
	}
	return newVal
}

func formatZZZZZZZZ9_99(d decimal.Decimal) string {
	// PIC ZZ,ZZZ,ZZ9.99  len 13
	// d assumed already scaled to 2 decimals (rounded/truncated)
	// handle sign: COBOL would show sign? ignore for positive; for negative show minus?
	neg := d.IsNegative()
	if neg {
		d = d.Neg()
	}
	// drop high-order digits beyond 8 integer digits (as per MOVE to edited)
	// Ensure integer part modulo 10^8
	intPart := d.Truncate(0)
	modulus := decimal.New(100000000, 0)
	if intPart.GreaterThanOrEqual(modulus) {
		intPart = intPart.Mod(modulus)
		fracPart := d.Sub(d.Truncate(0).Abs())
		// Need to reconstruct with truncated intPart
		// fracPart originally based on original d's integer, but since we modded intPart, recompute frac correctly
		origInt := d.Truncate(0)
		frac := d.Sub(origInt)
		if neg {
			// orig d was negative, but we made positive; frac positive
		}
		d = intPart.Add(frac)
		intPart = d.Truncate(0)
	}
	// Get string with exactly 2 decimals
	// Use StringFixed to get 2 decimals
	s := d.StringFixed(2) // e.g. "1000.00" or "0.00"
	// split
	dot := strings.LastIndex(s, ".")
	var intStr, fracStr string
	if dot >= 0 {
		intStr = s[:dot]
		fracStr = s[dot+1:]
	} else {
		intStr = s
		fracStr = "00"
	}
	// handle negative intStr prefix
	if strings.HasPrefix(intStr, "-") {
		intStr = intStr[1:]
	}
	// intStr may have sign not; pad to 8 digits with leading zeros, or truncate high-order
	if len(intStr) > 8 {
		intStr = intStr[len(intStr)-8:]
	}
	// pad to 8
	if len(intStr) < 8 {
		intStr = strings.Repeat("0", 8-len(intStr)) + intStr
	}
	// fracStr ensure 2 chars
	if len(fracStr) < 2 {
		fracStr = fracStr + strings.Repeat("0", 2-len(fracStr))
	} else if len(fracStr) > 2 {
		fracStr = fracStr[:2]
	}
	// int digits array length 8
	digits := intStr // 8 chars
	// find first non-zero
	firstNonZero := -1
	for i, ch := range digits {
		if ch != '0' {
			firstNonZero = i
			break
		}
	}
	// map digit index to output pos
	// output integer section length 10: 0:Z 1:Z 2:, 3:Z 4:Z 5:Z 6:, 7:Z 8:Z 9:9
	outInt := make([]byte, 10)
	// digitPosMap: which out index corresponds to digit i
	digitPos := []int{0, 1, 3, 4, 5, 7, 8, 9}
	for i := 0; i < 8; i++ {
		p := digitPos[i]
		isLast := i == 7
		var ch byte
		if isLast {
			ch = digits[i]
		} else {
			if firstNonZero == -1 {
				// all zero -> suppress
				ch = ' '
			} else {
				if i < firstNonZero {
					ch = ' '
				} else {
					ch = digits[i]
				}
			}
		}
		outInt[p] = ch
	}
	// commas
	// comma at out index 2 left digits 0,1
	if firstNonZero != -1 && firstNonZero <= 1 {
		outInt[2] = ','
	} else {
		outInt[2] = ' '
	}
	if firstNonZero != -1 && firstNonZero <= 4 {
		outInt[6] = ','
	} else {
		outInt[6] = ' '
	}
	intSection := string(outInt)
	result := intSection + "." + fracStr
	// result length should be 13
	if neg {
		// COBOL edited picture without sign would maybe show? Put minus in first position if space?
		// Not needed for this program but handle: replace leading space with '-'
		// find first space to place '-'
		b := []byte(result)
		for i := 0; i < len(b); i++ {
			if b[i] == ' ' {
				continue
			}
			// place minus before first digit? Simplified: put at position i-1 if possible
			if i > 0 {
				b[i-1] = '-'
			} else {
				b[0] = '-'
			}
			break
		}
		result = string(b)
	}
	return result
}

func formatPic99(v int64, digits int) string {
	// zero-padded
	s := fmt.Sprintf("%d", v)
	if len(s) > digits {
		s = s[len(s)-digits:]
	}
	if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	}
	return s
}

func openSchedFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not exists, treat as empty
		schedLines = []string{}
		schedIndex = 0
		return
	}
	schedFile = f
	scanner := bufio.NewScanner(f)
	// increase buffer for long lines
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 1024*1024)
	for scanner.Scan() {
		line := scanner.Text()
		// strip trailing \r if any (Scanner already splits on \n, but handle \r)
		if len(line) > 0 && line[len(line)-1] == '\r' {
			line = line[:len(line)-1]
		}
		schedLines = append(schedLines, line)
	}
	// ignore scanner error
	schedIndex = 0
}

func closeSchedFile() {
	if schedFile != nil {
		schedFile.Close()
	}
}

func readPara() {
	if schedIndex >= len(schedLines) {
		WsEofFlag = "Y"
		return
	}
	raw := schedLines[schedIndex]
	schedIndex++
	// pad with spaces to 16
	if len(raw) < 16 {
		raw = raw + strings.Repeat(" ", 16-len(raw))
	} else if len(raw) > 16 {
		raw = raw[:16]
	}
	// parse fields
	scAcct := raw[0:4]
	scPrinRaw := raw[4:11]  // 7 bytes
	scRateRaw := raw[11:15] // 4 bytes
	scYearsRaw := raw[15:16]

	schedRec.ScAcct = scAcct
	schedRec.ScPrin = parseDigitsToDecimal(scPrinRaw, 2)
	schedRec.ScRate = parseDigitsToDecimal(scRateRaw, 2)
	schedRec.ScYears = parseIntField(scYearsRaw)
	WsEofFlag = "N"
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func mainPara() {
	openSchedFile()
	readPara()
	for !isInputDone() {
		processPara()
	}
	closeSchedFile()
	// DISPLAY "SCHEDULES: " WS-COUNT
	// WS-COUNT is PIC 99 zero-padded 2
	fmt.Printf("SCHEDULES: %s\n", formatPic99(WsCount, 2))
}

func processPara() {
	WsBal = schedRec.ScPrin
	// Ensure WsBal truncated to 9(8)V99? Move
	WsBal = WsBal.Truncate(2)
	WsBal = truncateToPic9_8V99(WsBal)

	WsYear = 1
	for !(WsYear > schedRec.ScYears) {
		// COMPUTE WS-BAL ROUNDED = WS-BAL * (1 + SC-RATE /100)
		rateDiv := schedRec.ScRate.Shift(-2) // /100
		onePlus := decimal.New(1, 0).Add(rateDiv)
		computed := WsBal.Mul(onePlus)
		rounded := computed.Round(2)
		// store with truncation of high-order digits
		rounded = truncateToPic9_8V99(rounded)
		WsBal = rounded

		WsBalEd = formatZZZZZZZZ9_99(WsBal)
		// DISPLAY SC-ACCT " Y" WS-YEAR " " WS-BAL-ED
		yearStr := formatPic99(WsYear, 2)
		fmt.Printf("%s Y%s %s\n", schedRec.ScAcct, yearStr, WsBalEd)

		WsYear++
	}
	WsBalEd = formatZZZZZZZZ9_99(WsBal)
	fmt.Printf("%s FINAL %s\n", schedRec.ScAcct, WsBalEd)
	WsCount++

	readPara()
}

func main() {
	mainPara()
}

